ControlPropertyState.AutoRuleBindingString:
// ———————————————————————————————————————————————————————————————
// Step 0) Reset all flags + result collections.
	Set(varCalendarOK, false );
// full 48-col main Patch succeeded (all rows)
	Set(varMainOK, false );
// simplified 10-col main Patch succeeded (all rows)
	Set(varMainSimpleOK, false );
// full 48-col backup Patch succeeded (all rows)
	Set(varBackupOK, false );
// simplified 10-col backup Patch succeeded (all rows)
	Set(varBackupSimpleOK, false );
	Set(varAllOK, false );
// Clear success/failure collections
	Clear(colMainFullResults);
	Clear(colMainSimpleResults);
	Clear(colBackupPatchResults);
// Set email outcome flag to false
    Set(varEmailOK, false);

// ———————————————————————————————————————————————————————————————
// Step 1) Outlook calendar item -> varCalendarOK.
	IfError(
		Office365Outlook.V4CalendarPostItem(
			LookUp(
				Office365Outlook.CalendarGetTables().value,
				DisplayName = "Calendar"
			).Name,
			Concatenate(
				"578 EHRM Learning Lab - ",
				var_reservationScenario
			),
			var_StartDateTime_central,
			var_EndDateTime_central,
			"Central Standard Time",
			{
				requiredAttendees: var_Attendees,
				optionalAttendees: var_Attendees,
				body: var_EmailBody,
				categories: varMeetCat,
				location: varSelectedDesk.CombinedLocationDetails_multilinePlainText,
				importance: "high",
				isAllDay: false,
				recurrence: varRecurrence,
				reminderMinutesBeforeStart: varReminder,
				isReminderOn: If(
					varReminder > 0,
					true,
					false
				),
				showAs: "busy",
				responseRequested: true,
				sensitivity: "normal"
			}
		),
// STEP 1b) varCalendarOK = boolean outcome of the V4CalendarPostItem action.
		Set(
			varCalendarOK,
			false
		),
		Set(
			varCalendarOK,
			true
		)
	);


// ———————————————————————————————————————————————————————————————
// STEP 2) Attempt MAIN FULL Patch (detailed 48 columns) for every row.
	ForAll(
		CollectionRecurrence As rec,
		ForAll(
			colSelectedDesks As desk,
			Collect(
				colMainFullResults,
				{
					ok: !IsError(
						Patch(
							'Desk Reservations',
							Defaults('Desk Reservations'),
							{
								// New Columns:
								Title: var_Attendees & " – " & var_MeetingCategory & " - " & var_reservationScenario & " (" & var_reservationRole & ")",
								submitterName_text: varMyProfile.displayName,
								submitterEmail_text: Lower(varMyProfile.mail),
								submitterService_text: If(IsBlankOrError(Office365Users.UserProfileV2(varRealEntraID).department),"",Office365Users.UserProfileV2(varRealEntraID).department) & If(IsBlankOrError(Office365Users.UserProfileV2(varRealEntraID).officeLocation),"",Office365Users.UserProfileV2(varRealEntraID).officeLocation) & If(IsBlankOrError(Office365Users.UserProfileV2(varRealEntraID).companyName),"",Office365Users.UserProfileV2(varRealEntraID).companyName), //If(IsBlankOrError(var_Service), "none provided", var_Service),
								studentName_text: varStudentProfile.displayName,
								studentEmail_text: Lower(varStudentProfile.mail),
								studentService_text: var_Service,
								studentTitle_text: varStudentProfile.jobTitle,
								studentManagerEmail_text: varStudentMgrMail,
								reservationRole_text: var_reservationRole,
								reservationScenario_text: var_reservationScenario,
								reservationStart_datetime: var_StartDateTime_central,
								reservationEnd_datetime: var_EndDateTime_central,
								reservationDesk_text: "Desk " & "1",
								reservationRoom_text: "Room " & var_reservationRoomNumber,
								reservationFloor_text: "Floor " & var_reservationFloorNumber,
								reservationBuilding_text: "Building " & var_reservationBuildingNumber,
								reservationDivision_text: var_reservationDivision,
								reservationAgreementBody_multilinetext: If(IsBlankOrError(var_reservationAgreementBody), HtmlText3.HtmlText, var_reservationAgreementBody),
								reservationDescription_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Self-registered student, for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")", Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), varRealEmail &  "has registered student (" & varStudentProfile.userPrincipalName & "), for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")" ),
								reservationComments_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Submitted by student @ " & Now(), Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), "Submitted by " & varRealEmail & " @ " & Now()),
								reservationInviteBody_multilinetext: var_EmailBody,
								reservationInviteOptionalAttendees_multilinetext: var_OptionalAttendees,

								// OLD Columns:
								MeetingCategory: var_MeetingCategory,
								DeskText: var_reservationScenario & " (" & var_reservationRole & ")",
								Description: var_reservationScenario & " (" & var_reservationRole & ")",
								Active_choice: {Value: Text("true")},
								'Check Out To': var_StartDateTime_central,
								'Check Out From': var_EndDateTime_central,
								'Check Out To Text': Text(var_EndTime_central),
								'Check Out From Text': Text(var_StartTime_central),
								'Check Out From Number': Value(Substitute(Substitute(Substitute(Substitute(var_StartTime_central, "PM", ""), "AM", ""), ":", ""), " ", "")),
								'Check Out To Number': Value(Substitute(Substitute(Substitute(Substitute(var_EndTime_central, "PM", ""), "AM", ""), ":", ""), " ", "")),
								Service: var_Service,
								RoomReservation: true,
								Asset: {Value: "Desk"},
								RecurrenceFrequency: {Value: varRecurrence},
								RecurrenceEndDate: Date(Year(var_EndDateTime_central),Month(var_EndDateTime_central),Day(var_EndDateTime_central)),
								RecurrenceID: varRecurrenceID,
								RecurrenceDayName: If(IsBlankOrError(var_DayOfWeek), Blank(), var_DayOfWeek),
								RecurrenceTimes: If(IsBlankOrError(Time(Hour(var_StartDateTime_central),Minute(var_StartDateTime_central),Second(var_StartDateTime_central))), Blank(), Time(Hour(var_StartDateTime_central),Minute(var_StartDateTime_central),Second(var_StartDateTime_central))),
								RecurrencePattern: Blank(),
                                OptionalAttendees: Blank(),
								IsRecurring: false,
								OutlookEventID: Blank(),
								OutlookSeriesID: Blank(),
								ParentReservationID: Blank()
							}
						)
					)
				}
			)
		)
	);
// STEP 2b) varMainOK = boolean outcome of the FULL Patch (all rows OK).
	Set(
		varMainOK,
		CountRows(colMainFullResults) > 0 And CountIf(colMainFullResults, Not(ok)) = 0
	);

// ———————————————————————————————————————————————————————————————
// STEP 3) If MAIN FULL Patch (step #2 & #2b) failed -> attempt SIMPLE fallback; else skip it.
	If(
		Not(varMainOK),
		ForAll(
			CollectionRecurrence As recS,
			ForAll(
				colSelectedDesks As deskS,
				Collect(
					colMainSimpleResults,
					{
						ok: !IsError(
							Patch(
								'Desk Reservations',
								Defaults('Desk Reservations'),
								{
									Title: var_Attendees & " – " & var_MeetingCategory & " - " & var_reservationScenario & " (" & var_reservationRole & ")",
									submitterName_text: varMyProfile.displayName,
									submitterEmail_text: Lower(varMyProfile.mail),
									studentName_text: varStudentProfile.displayName,
									studentEmail_text: Lower(varStudentProfile.mail),
									reservationRole_text: var_reservationRole,
									reservationScenario_text: var_reservationScenario,
									reservationStart_datetime: var_StartDateTime_central,
									reservationEnd_datetime: var_EndDateTime_central,
									Active_choice: {Value: Text("true")},
                                    reservationDescription_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Self-registered student, for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")", Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), varRealEmail &  "has registered student (" & varStudentProfile.userPrincipalName & "), for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")" ),
								    reservationComments_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Submitted by student @ " & Now(), Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), "Submitted by " & varRealEmail & " @ " & Now())
								}
							)
						)
					}
				)
			)
		)
	);
// STEP 3b) varMainSimpleOK = boolean outcome of the simple fallback action.
	Set(
		varMainSimpleOK,
		CountRows(colMainSimpleResults) > 0 And CountIf(
			colMainSimpleResults,
			Not(ok)
		) = 0
	);

// ———————————————————————————————————————————————————————————————
// STEP 4) Attempt detailed backup Patch for every colBackupPatchResults (runs regardless of main outcome)
	ForAll(
		CollectionRecurrence As rec,
		ForAll(
			colSelectedDesks As desk,
			Collect(
				colMainFullResults,
				{
					ok: !IsError(
						Patch(
							backupList_DeskReservations,
							Defaults('Desk Reservations'),
							{
								// New Columns:
								Title: var_Attendees & " – " & var_MeetingCategory & " - " & var_reservationScenario & " (" & var_reservationRole & ")",
								submitterName_text: varMyProfile.displayName,
								submitterEmail_text: Lower(varMyProfile.mail),
								submitterService_text: If(IsBlankOrError(Office365Users.UserProfileV2(varRealEntraID).department),"",Office365Users.UserProfileV2(varRealEntraID).department) & If(IsBlankOrError(Office365Users.UserProfileV2(varRealEntraID).officeLocation),"",Office365Users.UserProfileV2(varRealEntraID).officeLocation) & If(IsBlankOrError(Office365Users.UserProfileV2(varRealEntraID).companyName),"",Office365Users.UserProfileV2(varRealEntraID).companyName),
								studentName_text: varStudentProfile.displayName,
								studentEmail_text: Lower(varStudentProfile.mail),
								studentService_text: var_Service,
								studentTitle_text: varStudentProfile.jobTitle,
								studentManagerEmail_text: varStudentMgrMail,
								reservationRole_text: var_reservationRole,
								reservationScenario_text: var_reservationScenario,
								reservationStart_datetime: var_StartDateTime_central,
								reservationEnd_datetime: var_EndDateTime_central,
								reservationDesk_text: "Desk " & "1",
								reservationRoom_text: "Room " & var_reservationRoomNumber,
								reservationFloor_text: "Floor " & var_reservationFloorNumber,
								reservationBuilding_text: "Building " & var_reservationBuildingNumber,
								reservationDivision_text: var_reservationDivision,
								reservationAgreementBody_multilinetext: If(IsBlankOrError(var_reservationAgreementBody), HtmlText3.HtmlText, var_reservationAgreementBody),
								reservationDescription_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Self-registered student, for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")", Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), varRealEmail &  "has registered student (" & varStudentProfile.userPrincipalName & "), for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")" ), //var_reservationScenario & " (" & var_reservationRole & ")",
								reservationComments_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Submitted by student @ " & Now(), Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), "Submitted by " & varRealEmail & " @ " & Now()),
								reservationInviteBody_multilinetext: var_EmailBody,
								reservationInviteOptionalAttendees_multilinetext: var_OptionalAttendees,

								// OLD Columns:
								MeetingCategory: var_MeetingCategory,
								DeskText: var_reservationScenario & " (" & var_reservationRole & ")",
								Description: var_reservationScenario & " (" & var_reservationRole & ")",
								Active_choice: {Value: Text("true")},
								'Check Out To': var_StartDateTime_central,
								'Check Out From': var_EndDateTime_central,
								'Check Out To Text': Text(var_EndTime_central),
								'Check Out From Text': Text(var_StartTime_central),
								'Check Out From Number': Value(Substitute(Substitute(Substitute(Substitute(var_StartTime_central, "PM", ""), "AM", ""), ":", ""), " ", "")),
								'Check Out To Number': Value(Substitute(Substitute(Substitute(Substitute(var_EndTime_central, "PM", ""), "AM", ""), ":", ""), " ", "")),
								Service: var_Service,
								RoomReservation: true,
								Asset: {Value: "Desk"},
								RecurrenceFrequency: {Value: varRecurrence},
								RecurrenceEndDate: Date(Year(var_StartDateTime_central),Month(var_StartDateTime_central),Day(var_StartDateTime_central)),
								RecurrenceID: varRecurrenceID,
								RecurrenceDayName: If(IsBlankOrError(var_DayOfWeek), Blank(), var_DayOfWeek),
								RecurrenceTimes: If(IsBlankOrError(Time(Hour(var_StartDateTime_central),Minute(var_StartDateTime_central),Second(var_StartDateTime_central))), Blank(), Time(Hour(var_StartDateTime_central),Minute(var_StartDateTime_central),Second(var_StartDateTime_central))),
								RecurrencePattern: Blank(),
								IsRecurring: false,
								OutlookEventID: Blank(),
								OutlookSeriesID: Blank(),
								ParentReservationID: Blank()
							}
						)
					)
				}
			)
		)
	);
// STEP 4b) varBackupOK = boolean outcome of the main backup patch action.
	Set(
		varBackupOK,
		CountRows(colBackupPatchResults) > 0 And CountIf(
			colBackupPatchResults,
			Not(ok)
		) = 0
	);

// ———————————————————————————————————————————————————————————————
// STEP 5) Attempt simplified backup Patch for every colBackupPatchResults (runs regardless of main outcome)
	If(
		Not(varBackupOK),
		ForAll(
			CollectionRecurrence As recBk,
			ForAll(
				colSelectedDesks As deskBk,
				Collect(
					colBackupPatchResults,
					{
						ok: !IsError(
							Patch(
								backupList_DeskReservations,
								Defaults('Desk Reservations'),
								{
									Title: var_Attendees & " – " & var_MeetingCategory & " - " & var_reservationScenario & " (" & var_reservationRole & ")",
									submitterName_text: varMyProfile.displayName,
									submitterEmail_text: Lower(varMyProfile.mail),
									studentName_text: varStudentProfile.displayName,
									studentEmail_text: Lower(varStudentProfile.mail),
									reservationRole_text: var_reservationRole,
									reservationScenario_text: var_reservationScenario,
									reservationStart_datetime: var_StartDateTime_central,
									reservationEnd_datetime: var_EndDateTime_central,
									Active_choice: {Value: Text("true")},
                                    reservationDescription_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Self-registered student, for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")", Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), varRealEmail &  "has registered student (" & varStudentProfile.userPrincipalName & "), for EHRM Learning Lab:" & var_reservationScenario & " (" & var_reservationRole & ")" ),
								    reservationComments_multilinetext: If(Lower(varStudentProfile.userPrincipalName) = Lower(varRealEmail), "Submitted by student @ " & Now(), Lower(varStudentProfile.userPrincipalName) <> Lower(varRealEmail), "Submitted by " & varRealEmail & " @ " & Now())
								}
							)
						)
					}
				)
			)
		)
    );
// STEP 5b) varBackupOK = boolean outcome of the main backup patch action.
	Set(
		varBackupSimpleOK,
		CountRows(colBackupPatchResults) > 0 And CountIf(
			colBackupPatchResults,
			Not(ok)
		) = 0
	);


// ———————————————————————————————————————————————————————————————
// STEP 6) Patch the SuperUserList (only if the user's email exists)
// Grab the matching row once
Set(
    varSuperUserRow,
    LookUp(
        SuperUserList,
        Lower('Enter Super User VA email address') = Lower(varMyProfile.mail)
    )
);
If(
    !IsBlank(varSuperUserRow),
    // Build this event's single-line string
    Set(
        varNewEventLine,
        "Event: " & Text(
            var_StartDateTime_central,
            "m/d/yyyy h:mm AM/PM"
        ) & "; Scenario: " & var_reservationScenario & "; Role: " & var_reservationRole & ";"
    );
    IfError(
        Patch(
            SuperUserList,
            varSuperUserRow,
            {
                // First three columns: only stamp if currently blank
                LearningLab_Scheduled_datetime:
                    If(
                        IsBlank(varSuperUserRow.LearningLab_Scheduled_datetime),
                        var_StartDateTime_central,
                        varSuperUserRow.LearningLab_Scheduled_datetime
                ),
                LearningLab_ScenarioName:
                    If(
                        IsBlank(varSuperUserRow.LearningLab_ScenarioName),
                        var_reservationScenario,
                        varSuperUserRow.LearningLab_ScenarioName
                    ),
                LearningLab_RoleName:
                    If(
                        IsBlank(varSuperUserRow.LearningLab_RoleName),
                        var_reservationRole,
                        varSuperUserRow.LearningLab_RoleName
                    ),
                // Multi-text column: append a new line every time
                LearningLab_multiScenario_multipletext:
                    If(
                        IsBlank(varSuperUserRow.LearningLab_multiScenario_multipletext),
                        varNewEventLine,
                        varSuperUserRow.LearningLab_multiScenario_multipletext & Char(10) & varNewEventLine
                    )
            }
        ),
        // STEP 7b) varPatchSuperUsersOK = boolean outcome of the patch SuperUserList action.
        Set(varPatchSuperUsersOK, false),
        // On success -> true.
        Set(varPatchSuperUsersOK, true)
    )
);



// ———————————————————————————————————————————————————————————————
// Step 7) Send the confirmation email (separate from the calendar item).
IfError(
    Office365Outlook.SendEmailV2(
        // To: (required)
        Concatenate(var_Attendees, "; "),
        // Subject: (required)
        Concatenate(
            "[REGISTERED] EHRM Learning Lab Training - ",
            var_reservationScenario,
            " (",
            var_reservationRole,
            ")"
        ),
        // Body: (required)
        var_EmailBody,
        // Optional advanced parameters:
        {
            Importance: "Normal", //"Low", "Normal", "High"
            IsHtml: true,
            Cc: Concatenate(varAttendees, "; "/*, "VHAHINInformaticsTrainingAndSupport@va.gov; ",*/),
            Bcc: "Kyle.Coder@va.gov",
            ReplyTo: "VHAHINInformaticsTrainingAndSupport@va.gov"
        }
    ),
// STEP 7b) varBackupOK = boolean outcome of the main backup patch action.
    Set(varEmailOK, false),
    // On success -> true.
    Set(varEmailOK, true)
);

// ———————————————————————————————————————————————————————————————
// STEP 8) Combined flag varAllOK variable if all other preceeding steps pass/fail.
// Main list is considered saved if EITHER the full OR the simple
// Patch succeeded. Overall OK requires calendar + backup + main.
	Set(
		varAllOK,
		varCalendarOK And (varMainOK Or varMainSimpleOK) And (varBackupOK Or varBackupSimpleOK) And varEmailOK And varPatchSuperUsersOK
	);



// ———————————————————————————————————————————————————————————————
// STEP 9) Cleanup ONLY on full success.
	If(
		varAllOK,
		Concurrent(
			Set(
				varAccept,
				Blank()
			),
			Set(
				varAccept3,
				Blank()
			),
			Set(
				varAccept4,
				Blank()
			),
			ResetForm(Form1),
			Reset(ddImportance),
			Reset(ddRecurrenceFrequency),
			Reset(Calendar_1),
			Reset(Gallery6),
			Reset(DatePickerCanvas2),
			Reset(Gallery3_1),
			Clear(colSelectedDesks),
			Clear(CollectionRecurrence),
			Clear(colDeskChckRecur),
			Clear(colCombinedRecurrence),
			Clear(wkDays),
			Clear(wkDaysTemp)
		)
	);


// ———————————————————————————————————————————————————————————————
// Step 10)  Navigate to Confirmation screen.
If(
    Lower(User().Email) = "kyle.coder@va.gov" && App.Testing,
    Navigate(DebuggingScreen),
    Navigate(Success)
);

// ———————————————————————————————————————————————————————————————
// 1) Save item(s) to Outlook
Office365Outlook.V4CalendarPostItem(
    LookUp(Office365Outlook.CalendarGetTables().value, DisplayName = "Calendar").Name,
    Concatenate(
        "578 EHRM Learning Lab - ",
        var_reservationScenario
    ),
    var_StartDateTime_central,
    var_EndDateTime_central,
    "Central Standard Time",
    {
        requiredAttendees: var_Attendees,
        optionalAttendees: var_Attendees,
        body: var_EmailBody,
        categories: varMeetCat,
        location: varSelectedDesk.CombinedLocationDetails_multilinePlainText,
        importance: "high",
        isAllDay: false,
        recurrence: varRecurrence,
        reminderMinutesBeforeStart: varReminder,
        isReminderOn: If(varReminder > 0, true, false),
        showAs: "busy",
        responseRequested: true,
        sensitivity: "normal"
    }
);

// ———————————————————————————————————————————————————————————————
// 2) BACKUP Patch FIRST — decoupled, guarantees core data is captured
//    no matter what else on this button succeeds or fails.
ForAll(
    CollectionRecurrence As recBk,
    ForAll(
        colSelectedDesks As deskBk,
        IfError(
            Patch(
                backupList_DeskReservations,   // <-- change to your real backup list name
                Defaults('Desk Reservations - Backup'),
                {
                    Title: var_Attendees & " – " & var_MeetingCategory & " - " & var_reservationScenario & " (" & var_reservationRole & ")",
                    submitterName_text: Office365Users.MyProfileV2().displayName,
                    submitterEmail_text: Lower(Office365Users.MyProfileV2().mail),
                    studentName_text: Office365Users.UserProfileV2(var_Attendees).displayName,
                    studentEmail_text: Lower(Office365Users.UserProfileV2(var_Attendees).mail),
                    reservationRole_text: var_reservationRole,
                    reservationScenario_text: var_reservationScenario,
                    reservationStart_datetime: var_StartDateTime_central,
                    reservationEnd_datetime: var_EndDateTime_central,
                    Active_choice: {Value: Text("true")}
                }
            )
        )
    )
);

// ———————————————————————————————————————————————————————————————
// 3) MAIN Patch to SharePoint list — full 48 columns, with a
//    simplified fallback if the full Patch errors.
ForAll(
    CollectionRecurrence As rec,
    ForAll(
        colSelectedDesks As desk,
        IfError(

            // ——— TRY: full Patch ———
            Patch(
                'Desk Reservations',
                Defaults('Desk Reservations'),
                {
                    // New Columns:
                    Title: var_Attendees & " – " & var_MeetingCategory & " - " & var_reservationScenario & " (" & var_reservationRole & ")",
                    submitterName_text: Office365Users.MyProfileV2().displayName,
                    submitterEmail_text: Lower(Office365Users.MyProfileV2().mail),
                    submitterService_text: var_Service,
                    studentName_text: Office365Users.UserProfileV2(var_Attendees).displayName,
                    studentEmail_text: Lower(Office365Users.UserProfileV2(var_Attendees).mail),
                    studentService_text: var_Service,
                    studentTitle_text: Office365Users.UserProfileV2(var_Attendees).jobTitle,
                    studentManagerEmail_text: Lower(Office365Users.ManagerV2(var_Attendees).mail),
                    reservationRole_text: var_reservationRole,
                    reservationScenario_text: var_reservationScenario,
                    reservationStart_datetime: var_StartDateTime_central,
                    reservationEnd_datetime: var_EndDateTime_central,
                    reservationDesk_text: "Desk " & "1",
                    reservationRoom_text: "Room " & var_reservationRoomNumber,
                    reservationFloor_text: "Floor " & var_reservationFloorNumber,
                    reservationBuilding_text: "Building " & var_reservationBuildingNumber,
                    reservationDivision_text: var_reservationDivision,
                    reservationAgreementBody_multilinetext: var_reservationAgreementBody,
                    reservationDescription_multilinetext: var_reservationScenario & " (" & var_reservationRole & ")",
                    reservationComments_multilinetext: Blank(),
                    reservationInviteBody_multilinetext: var_EmailBody,
                    reservationInviteOptionalAttendees_multilinetext: var_OptionalAttendees,

                    // OLD Columns:
                    MeetingCategory: var_MeetingCategory,
                    DeskText: var_reservationScenario & " (" & var_reservationRole & ")",
                    Description: var_reservationScenario & " (" & var_reservationRole & ")",
                    Active_choice: {Value: Text("true")},
                    'Check Out To': var_StartDateTime_central,
                    'Check Out From': var_EndDateTime_central,
